package meiall

import scala.xml.*

object MeiXML {

  def load(xml: Elem): _root_.meiall.mei.shared.Mei = {
    loadElement(xml) match {
      case m: _root_.meiall.mei.shared.Mei => m
      case other => throw new IllegalArgumentException(s"Root element must be 'mei', but got ${other.getClass.getSimpleName}")
    }
  }

  def loadElement(node: Node): meiall.Element = node match {
    case e: Elem =>
      val attributes: scala.collection.immutable.SeqMap[String, String] = scala.collection.immutable.SeqMap.from(
        e.attributes.map {
          case p: scala.xml.PrefixedAttribute => (s"${p.pre}:${p.key}", p.value.text)
          case u: scala.xml.UnprefixedAttribute => (u.key, u.value.text)
          case m => (m.key, m.value.text)
        }
      )
      val children = e.child.flatMap { n => 
        loadElement(n) match {
          case t: meiall.Text if t.value.trim.isEmpty => None // No blank Text nodes are created
          case other => Some(other)
        }
      }.toList
      
      e.label match {
      case "abbr" => _root_.meiall.mei.edittrans.Abbr(children, attributes)
      case "accMat" => _root_.meiall.mei.msdesc.AccMat(children, attributes)
      case "accessRestrict" => _root_.meiall.mei.header.AccessRestrict(children, attributes)
      case "accid" => _root_.meiall.mei.shared.Accid(children, attributes)
      case "acquisition" => _root_.meiall.mei.header.Acquisition(children, attributes)
      case "actor" => _root_.meiall.mei.shared.Actor(children, attributes)
      case "add" => _root_.meiall.mei.edittrans.Add(children, attributes)
      case "addDesc" => _root_.meiall.mei.msdesc.AddDesc(children, attributes)
      case "addName" => _root_.meiall.mei.namesdates.AddName(children, attributes)
      case "addrLine" => _root_.meiall.mei.shared.AddrLine(children, attributes)
      case "address" => _root_.meiall.mei.shared.Address(children, attributes)
      case "altId" => _root_.meiall.mei.header.AltId(children, attributes)
      case "ambNote" => _root_.meiall.mei.shared.AmbNote(children, attributes)
      case "ambitus" => _root_.meiall.mei.shared.Ambitus(children, attributes)
      case "analytic" => _root_.meiall.mei.shared.Analytic(children, attributes)
      case "anchoredText" => _root_.meiall.mei.usersymbols.AnchoredText(children, attributes)
      case "annot" => _root_.meiall.mei.shared.Annot(children, attributes)
      case "app" => _root_.meiall.mei.critapp.App(children, attributes)
